    /// <summary>
    /// Checks the approved PNG bytes and RGBA pixels at their original review dimensions.
    /// </summary>
    /// <returns>A task completing after all standalone snapshots and locked access are checked.</returns>
    [Fact]
    public async Task ApprovedStandaloneArtworkRetainsExactDisplayPixels()
    {
        Dictionary<Guid, string[]> expected = JsonSerializer.Deserialize<Dictionary<Guid, string[]>>(_assignedStandaloneHashes)!;
        HashSet<Guid> known = [.. new AchievementPack().Nodes.Select(node => node.Id)];
        using TestDirectory directory = new();
        await using GameplayCollectionStore store = new(directory.Path);
        Assert.Equal(70, expected.Count);
        HashSet<Guid> approved = [.. JsonSerializer.Deserialize<Dictionary<Guid, string>>(_assignedStageHashes)!.Keys, .. JsonSerializer.Deserialize<Dictionary<Guid, string>>(_assignedItemHashes)!.Keys, .. expected.Keys];
        Assert.Equal(known.Order(), approved.Order());
        Assert.All(approved, id => Assert.NotNull(AchievementIconPack.Shared.AssignedIconId(id)));
        Assert.Empty(await store.GetAchievementIconsAsync(expected.Keys));
        foreach (var assignment in expected)
        {
            Assert.Contains(assignment.Key, known);
            var icon = AchievementIconPack.Shared.ForEarned(assignment.Key);
            byte[] pixels = Convert.FromBase64String(icon.Pixels);
            Assert.Equal(50, icon.Width);
            Assert.Equal(50, icon.Height);
            Assert.Equal(10000, pixels.Length);
            Assert.StartsWith(_standalonePngPrefix, icon.ImageDataUri);
            byte[] png = Convert.FromBase64String(icon.ImageDataUri[_standalonePngPrefix.Length..]);
            Assert.Equal(assignment.Value[0], Convert.ToHexString(SHA256.HashData(png)));
            Assert.Equal(assignment.Value[1], Convert.ToHexString(SHA256.HashData(pixels)));
            Assert.Contains(Enumerable.Range(0, icon.Width * icon.Height), index => pixels[index * 4 + 3] == 0);
            Assert.Contains(Enumerable.Range(0, icon.Width * icon.Height), index => pixels[index * 4 + 3] == 255);
        }

        Assert.Empty(await store.GetAchievementIconsAsync(expected.Keys));
        Assert.Empty(await store.GetAchievementsAsync());
        Assert.Empty(Directory.EnumerateFiles(directory.Path, _assignedImagePattern, SearchOption.AllDirectories));
    }
}
